/** Ask the person for a permission. Resolves when they answer. */
export interface PermRequestRequest {
  id: RequestId;
  method: "perm.request";
  params: PermRequestParams;
}

/** Parameters of perm.request. */
export interface PermRequestParams {
  permission: Permission;
  /** Shown to the person in the prompt. */
  reason: string;
  duration?: GrantDuration;
}

/** How long a grant lasts. once: the next call it allows, then it expires. session: until Desk quits. always: kept on disk across restarts. Every grant lasts until revoked at the latest. perm.request defaults to session. */
export type GrantDuration = "once" | "session" | "always";

/** Result of perm.request. A refusal is a result, not an error. */
export interface PermRequestResult {
  granted: boolean;
  grant?: Grant;
}

/** List the caller's current grants. */
export interface PermQueryRequest {
  id: RequestId;
  method: "perm.query";
  params: PermQueryParams;
}

/** Parameters of perm.query. With permission, only grants that cover it are returned. */
export interface PermQueryParams {
  permission?: Permission;
}

/** Result of perm.query. */
export interface PermQueryResult {
  grants: Grant[];
}

/** Give a grant back. The person can also revoke any grant at any time. */
export interface PermRevokeRequest {
  id: RequestId;
  method: "perm.revoke";
  params: PermRevokeParams;
}

/** Parameters of perm.revoke. Without scope only the caller's own grants; with perm:manage any caller's. */
export interface PermRevokeParams {
  grantId: string;
  scope?: PermManagePermission;
}

/** Result of perm.revoke. */
export type PermRevokeResult = Record<string, never>;

/** A permission the person granted to the caller. */
export interface Grant {
  grantId: string;
  permission: Permission;
  duration: GrantDuration;
  /** RFC 3339 timestamp. */
  grantedAt: string;
  /** RFC 3339 timestamp; absent means for as long as the duration allows. */
  expiresAt?: string;
}

/** List every caller's grants, for the person's permissions view. */
export interface PermListRequest {
  id: RequestId;
  method: "perm.list";
  params: PermListParams;
}

/** Parameters of perm.list. With caller, only that caller's grants are returned. */
export interface PermListParams {
  caller?: CallerId;
  scope: PermManagePermission;
}

/** Result of perm.list, oldest grant first. */
export interface PermListResult {
  grants: CallerGrant[];
}

/** A grant together with the caller that holds it. */
export interface CallerGrant {
  caller: CallerId;
  grant: Grant;
}

/** The prompter answers a perm.prompt with the person's decision. */
export interface PermAnswerRequest {
  id: RequestId;
  method: "perm.answer";
  params: PermAnswerParams;
}

/** Parameters of perm.answer. duration is what the person chose; absent keeps the one asked for. */
export interface PermAnswerParams {
  promptId: string;
  granted: boolean;
  duration?: GrantDuration;
  scope: PermManagePermission;
}

/** Result of perm.answer. */
export type PermAnswerResult = Record<string, never>;

/** A caller asked for a permission and the person has to decide. Sent to callers that hold perm:manage. */
export interface PermPromptEvent {
  event: "perm.prompt";
  data: PermPromptData;
}

/** Payload of perm.prompt: who asks, for what, why and for how long. */
export interface PermPromptData {
  promptId: string;
  caller: CallerId;
  permission: Permission;
  /** The caller's reason, to show as it is. */
  reason: string;
  duration: GrantDuration;
}

/** One of the caller's grants changed. */
export interface PermChangedEvent {
  event: "perm.changed";
  data: PermChangedData;
}

/** Payload of perm.changed. */
export interface PermChangedData {
  grantId: string;
  change: GrantChange;
}

/** What happened to the grant. */
export type GrantChange = "granted" | "revoked" | "expired";

/** List every installed plugin with its state. */
export interface PluginListRequest {
  id: RequestId;
  method: "plugin.list";
  params: PluginListParams;
}

/** Parameters of plugin.list. */
export interface PluginListParams {
  scope: PluginManagePermission;
}

/** Result of plugin.list, in install order. */
export interface PluginListResult {
  plugins: PluginInfo[];
}

/** One installed plugin. A failed plugin has no manifest it can run with and says why. */
export interface PluginInfo {
  id: PluginId;
  status: PluginStatus;
  enabled: boolean;
  /** Shipped with Desk. */
  builtIn: boolean;
  /** Increases every time the plugin's files change. */
  revision: number;
  manifest?: PluginManifest;
  /** Why the plugin failed, for people. */
  error?: string;
}

/** ready: the manifest is valid and the entry exists; failed: it cannot run. */
export type PluginStatus = "ready" | "failed";

/** Turn a plugin on or off. The choice is remembered. */
export interface PluginSetEnabledRequest {
  id: RequestId;
  method: "plugin.setEnabled";
  params: PluginSetEnabledParams;
}

/** Parameters of plugin.setEnabled. */
export interface PluginSetEnabledParams {
  plugin: PluginId;
  enabled: boolean;
  scope: PluginManagePermission;
}

/** Result of plugin.setEnabled: the plugin after the change. */
export interface PluginSetEnabledResult {
  plugin: PluginInfo;
}

/** A plugin was installed, updated on disk, removed, enabled or disabled. */
export interface PluginChangedEvent {
  event: "plugin.changed";
  data: PluginChangedData;
}

/** Payload of plugin.changed. */
export interface PluginChangedData {
  plugin: PluginId;
  change: PluginChange;
  revision: number;
}

/** What happened to the plugin. */
export type PluginChange = "installed" | "updated" | "removed" | "enabled" | "disabled";

/** Start a program. Output arrives as proc.output events, the end as proc.exit. */
export interface ProcSpawnRequest {
  id: RequestId;
  method: "proc.spawn";
  params: ProcSpawnParams;
}

/** Parameters of proc.spawn. */
export interface ProcSpawnParams {
  command: Command;
  /** Arguments, passed without a shell. */
  args?: string[];
  cwd?: Path;
  /** Extra environment variables. */
  env?: Record<string, string>;
  pty?: PtySize;
  scope: ProcSpawnPermission;
}

/** Terminal size. Present on spawn means: run in a PTY. */
export interface PtySize {
  cols: number;
  rows: number;
}

/** Result of proc.spawn. */
export interface ProcSpawnResult {
  /** Names the process in later calls and events. */
  procId: string;
  /** The OS process id, when known. */
  pid?: number;
}

/** Write to a process's stdin or PTY. */
export interface ProcWriteRequest {
  id: RequestId;
  method: "proc.write";
  params: ProcWriteParams;
}

/** Parameters of proc.write. */
export interface ProcWriteParams {
  procId: string;
  data: string;
  encoding?: Encoding;
  scope: ProcSpawnPermission;
}

/** Result of proc.write. */
export type ProcWriteResult = Record<string, never>;

/** Resize the PTY of a process started with pty. */
export interface ProcResizeRequest {
  id: RequestId;
  method: "proc.resize";
  params: ProcResizeParams;
}

/** Parameters of proc.resize. */
export interface ProcResizeParams {
  procId: string;
  size: PtySize;
  scope: ProcSpawnPermission;
}

/** Result of proc.resize. */
export type ProcResizeResult = Record<string, never>;

/** Send a signal to a process (term by default). */
export interface ProcKillRequest {
  id: RequestId;
  method: "proc.kill";
  params: ProcKillParams;
}

/** Parameters of proc.kill. */
export interface ProcKillParams {
  procId: string;
  signal?: Signal;
  scope: ProcSpawnPermission;
}

/** Result of proc.kill. */
export type ProcKillResult = Record<string, never>;

/** Portable signal names; Windows maps them to process termination. */
export type Signal = "term" | "kill" | "int" | "hup";

/** A process wrote output. */
export interface ProcOutputEvent {
  event: "proc.output";
  data: ProcOutputData;
}

/** Payload of proc.output. */
export interface ProcOutputData {
  procId: string;
  stream: OutputStream;
  data: string;
  encoding: Encoding;
}

/** Where the output came from. A PTY merges stdout and stderr. */
export type OutputStream = "stdout" | "stderr" | "pty";

/** A process ended. */
export interface ProcExitEvent {
  event: "proc.exit";
  data: ProcExitData;
}

/** Payload of proc.exit: an exit code, or the signal that ended it. */
export interface ProcExitData {
  procId: string;
  code?: number;
  signal?: Signal;
}

/** A key in its owner's namespace, lowercase and dotted: voice, motion.reduce. */
export type SettingKey = string;

/** One setting with its owner. */
export interface Setting {
  owner: CallerId;
  key: SettingKey;
  /** Any JSON value. */
  value: unknown;
}

/** Read one setting: the caller's own, or another caller's under settings:read. */
export interface SettingsGetRequest {
  id: RequestId;
  method: "settings.get";
  params: SettingsGetParams;
}

/** Parameters of settings.get. owner defaults to the caller; another owner needs a scope that covers owner/key. */
export interface SettingsGetParams {
  key: SettingKey;
  owner?: CallerId;
  scope?: SettingsReadPermission;
}

/** Result of settings.get. value is absent when the key was never set. */
export interface SettingsGetResult {
  /** Any JSON value. */
  value?: unknown;
}

/** Write one of the caller's own settings (64 KiB of JSON at most). */
export interface SettingsSetRequest {
  id: RequestId;
  method: "settings.set";
  params: SettingsSetParams;
}

/** Parameters of settings.set. */
export interface SettingsSetParams {
  key: SettingKey;
  /** Any JSON value. */
  value: unknown;
}

/** Result of settings.set. */
export type SettingsSetResult = Record<string, never>;

/** List settings: the caller's own, or every setting a settings:read scope covers. */
export interface SettingsListRequest {
  id: RequestId;
  method: "settings.list";
  params: SettingsListParams;
}

/** Parameters of settings.list. Without scope, the caller's own settings; with one, every setting it covers, whoever owns it. */
export interface SettingsListParams {
  scope?: SettingsReadPermission;
}

/** Result of settings.list, by owner and then key. */
export interface SettingsListResult {
  settings: Setting[];
}

/** A setting changed. Sent to its owner, and to callers subscribed to settings.changed whose settings:read grant covers it. */
export interface SettingsChangedEvent {
  event: "settings.changed";
  data: Setting;
}

/** A key in the caller's own namespace. */
export type StoreKey = string;

/** Read one of the caller's values. */
export interface StoreGetRequest {
  id: RequestId;
  method: "store.get";
  params: StoreGetParams;
}

/** Parameters of store.get. */
export interface StoreGetParams {
  key: StoreKey;
}

/** Result of store.get. value is absent when the key was never set. */
export interface StoreGetResult {
  /** Any JSON value. */
  value?: unknown;
}

/** Write one of the caller's values (64 KiB of JSON at most). */
export interface StoreSetRequest {
  id: RequestId;
  method: "store.set";
  params: StoreSetParams;
}

/** Parameters of store.set. */
export interface StoreSetParams {
  key: StoreKey;
  /** Any JSON value. */
  value: unknown;
}

/** Result of store.set. */
export type StoreSetResult = Record<string, never>;

/** Open one of the surfaces the caller's manifest declares. */
export interface UiSurfaceOpenRequest {
  id: RequestId;
  method: "ui.surface.open";
  params: UiSurfaceOpenParams;
}

/** Parameters of ui.surface.open. */
export interface UiSurfaceOpenParams {
  /** A surface id from the manifest. */
  surface: string;
  placement?: SurfacePlacement;
  title?: string;
  scope: UiSurfacePermission;
}

/** Result of ui.surface.open. */
export interface UiSurfaceOpenResult {
  /** Names the open surface. */
  handle: string;
}

/** Close a surface the caller opened. */
export interface UiSurfaceCloseRequest {
  id: RequestId;
  method: "ui.surface.close";
  params: UiSurfaceCloseParams;
}

/** Parameters of ui.surface.close. */
export interface UiSurfaceCloseParams {
  handle: string;
  scope: UiSurfacePermission;
}

/** Result of ui.surface.close. */
export type UiSurfaceCloseResult = Record<string, never>;

/** Show a notification. */
export interface UiNotifyRequest {
  id: RequestId;
  method: "ui.notify";
  params: UiNotifyParams;
}

/** Parameters of ui.notify. */
export interface UiNotifyParams {
  title: string;
  body?: string;
  level?: NotifyLevel;
  scope: UiNotifyPermission;
}

/** How a notification is presented; info by default. */
export type NotifyLevel = "info" | "success" | "warning" | "error";

/** Result of ui.notify. */
export interface UiNotifyResult {
  notificationId: string;
}

/** A caller's ui.notify passed its permission check; the runtime shows it as its notify policy says. */
export interface UiNotifiedEvent {
  event: "ui.notified";
  data: UiNotifiedData;
}

/** Payload of ui.notified. */
export interface UiNotifiedData {
  notificationId: string;
  /** The plugin that asked. */
  caller: string;
  title: string;
  body?: string;
  level: NotifyLevel;
}

/** Params and result of each bridge method. */
export interface BridgeMethodMap {
  "fs.read": { params: FsReadParams; result: FsReadResult };
  "fs.write": { params: FsWriteParams; result: FsWriteResult };
  "fs.list": { params: FsListParams; result: FsListResult };
  "fs.watch": { params: FsWatchParams; result: FsWatchResult };
  "proc.spawn": { params: ProcSpawnParams; result: ProcSpawnResult };
  "proc.write": { params: ProcWriteParams; result: ProcWriteResult };
  "proc.resize": { params: ProcResizeParams; result: ProcResizeResult };
  "proc.kill": { params: ProcKillParams; result: ProcKillResult };
  "net.fetch": { params: NetFetchParams; result: NetFetchResult };
  "audio.capture.start": { params: AudioCaptureStartParams; result: AudioCaptureStartResult };
  "audio.capture.stop": { params: AudioCaptureStopParams; result: AudioCaptureStopResult };
  "ui.surface.open": { params: UiSurfaceOpenParams; result: UiSurfaceOpenResult };
  "ui.surface.close": { params: UiSurfaceCloseParams; result: UiSurfaceCloseResult };
  "ui.notify": { params: UiNotifyParams; result: UiNotifyResult };
  "perm.request": { params: PermRequestParams; result: PermRequestResult };
  "perm.query": { params: PermQueryParams; result: PermQueryResult };
  "perm.revoke": { params: PermRevokeParams; result: PermRevokeResult };
  "perm.list": { params: PermListParams; result: PermListResult };
  "perm.answer": { params: PermAnswerParams; result: PermAnswerResult };
  "plugin.list": { params: PluginListParams; result: PluginListResult };
  "plugin.setEnabled": { params: PluginSetEnabledParams; result: PluginSetEnabledResult };
  "store.get": { params: StoreGetParams; result: StoreGetResult };
  "store.set": { params: StoreSetParams; result: StoreSetResult };
  "init.get": { params: InitGetParams; result: InitGetResult };
  "brain.say": { params: BrainSayParams; result: BrainSayResult };
  "cmd.register": { params: CmdRegisterParams; result: CmdRegisterResult };
  "cmd.unregister": { params: CmdUnregisterParams; result: CmdUnregisterResult };
  "cmd.list": { params: CmdListParams; result: CmdListResult };
  "cmd.invoke": { params: CmdInvokeParams; result: CmdInvokeResult };
  "settings.get": { params: SettingsGetParams; result: SettingsGetResult };
  "settings.set": { params: SettingsSetParams; result: SettingsSetResult };
  "settings.list": { params: SettingsListParams; result: SettingsListResult };
  "log.write": { params: LogWriteParams; result: LogWriteResult };
  "log.tail": { params: LogTailParams; result: LogTailResult };
  "events.subscribe": { params: EventsSubscribeParams; result: EventsSubscribeResult };
  "events.unsubscribe": { params: EventsUnsubscribeParams; result: EventsUnsubscribeResult };
}

/** A bridge method name. */
export type BridgeMethod = keyof BridgeMethodMap;

/** Every bridge method, in spec order. */
export const BRIDGE_METHODS = [
  "fs.read",
  "fs.write",
  "fs.list",
  "fs.watch",
  "proc.spawn",
  "proc.write",
  "proc.resize",
  "proc.kill",
  "net.fetch",
  "audio.capture.start",
  "audio.capture.stop",
  "ui.surface.open",
  "ui.surface.close",
  "ui.notify",
  "perm.request",
  "perm.query",
  "perm.revoke",
  "perm.list",
  "perm.answer",
  "plugin.list",
  "plugin.setEnabled",
  "store.get",
  "store.set",
  "init.get",
  "brain.say",
  "cmd.register",
  "cmd.unregister",
  "cmd.list",
  "cmd.invoke",
  "settings.get",
  "settings.set",
  "settings.list",
  "log.write",
  "log.tail",
  "events.subscribe",
  "events.unsubscribe",
] as const satisfies readonly BridgeMethod[];
